            if dist < min_dist:
                min_dist = dist
                nearest_point = (px, py)
        return nearest_point

    # Robust movement planning function
    def move_towards(target):
        if not target:
            return [0, 0]
        dx = 0
        dy = 0
        if target[0] > x:
            dx = 1
        elif target[0] < x:
            dx = -1
        if target[1] > y:
            dy = 1
        elif target[1] < y:
            dy = -1
        return [dx, dy]

    if 'resource_collection' in game_mode:
        target = find_nearest(resources, own_pos)
        return move_towards(target)

    elif 'pursuit_evasion' in game_mode:
        target = find_nearest(opponents, own_pos)
        return move_towards(target)

    elif 'territory_control' in game_mode:
        target = find_nearest(territories, own_pos)
        return move_towards(target)

    # Default fallback to stay in place
    return [0, 0]

